'use strict';

/*
 * Sample parser for Stalker events. It's intended as an example
 * to understand the format, it's possible to optimize it more.
 * It produces disassembly for block, compile and exec events - which
 * is totally unnecessary but it's useful for debugging.
 *
 * parseEvents(events, callback);
 *
 * Parameters:
 *
 *   events - the events as got from onReceive()
 *   callback - a callback to be executed for each parsed event
 *
 * Example:

  Stalker.follow({
    events: {
      call: false,
      ret: false,
      exec: false,
      block: false,
      compile: true
    },
    onReceive: function (events) {
      console.log('[' + tid + '] onReceive!');
      parseEvents(events, function (event) {
        if (event.type === 'compile' || event.type === 'block') {
          console.log('\n' + event.begin + ' -> ' + event.end);
          console.log(event.code + '\n');
        }
      });
    }
  });
*/

var threads = {};

var EV_TYPE_NOTHING = 0;
var EV_TYPE_CALL = 1;
var EV_TYPE_RET = 2;
var EV_TYPE_EXEC = 4;
var EV_TYPE_BLOCK = 8;
var EV_TYPE_COMPILE = 16;

var intSize = Process.pointerSize;
var EV_STRUCT_SIZE = 2 * Process.pointerSize + 2 * intSize;

function parseEvents(blob, callback) {
    var len = getLen(blob);
    for (var i = 0; i !== len; i++) {
        var type = getType(blob, i);
        switch (type) {
            case EV_TYPE_CALL:
                callback(parseCallEvent(blob, i));
                break;
            case EV_TYPE_RET:
                callback(parseRetEvent(blob, i));
                break;
            case EV_TYPE_EXEC:
                callback(parseExecEvent(blob, i));
                break;
            case EV_TYPE_BLOCK:
                callback(parseBlockEvent(blob, i));
                break;
            case EV_TYPE_COMPILE:
                callback(parseCompileEvent(blob, i));
                break;
            default:
                console.log('Unsupported type ' + type);
                break;
        }
    }
}

function getType(blob, idx) {
    return parseInteger(blob, idx, 0);
}

function getLen(blob) {
    return blob.byteLength / EV_STRUCT_SIZE;
}

function parseCallEvent(blob, idx) {
    return {
        type: 'call',
        location: parsePointer(blob, idx, intSize),
        target: parsePointer(blob, idx, intSize + Process.pointerSize),
        depth: parseInteger(blob, idx, intSize + 2 * Process.pointerSize)
    };
}

function parseRetEvent(blob, idx) {
    var ev = parseCallEvent(blob, idx);
    ev.type = 'ret';
    return ev;
}

function parseExecEvent(blob, idx) {
    var loc = parsePointer(blob, idx, intSize);
    return {
        type: 'exec',
        location: loc,
        code: Instruction.parse(loc).toString()
    };
}

function parseBlockEvent(blob, idx) {
    var begin = parsePointer(blob, idx, intSize);
    var end = parsePointer(blob, idx, intSize + Process.pointerSize);
    var i = begin.add(0);
    var code = [];
    while (i.compare(end) < 0) {
        var instr = Instruction.parse(i);
        code.push(i.toString() + '    ' + instr.toString());
        i = instr.next;
    }
    return {
        type: 'block',
        begin: begin,
        end: end,
        code: code.join('\n')
    };
}

function parseCompileEvent(blob, idx) {
    var parsed = parseBlockEvent(blob, idx);
    parsed.type = 'compile';
    return parsed;
}

function parseInteger(blob, idx, offset) {
    return new Int32Array(blob, idx * EV_STRUCT_SIZE + offset, 1)[0];
}

function parsePointer(blob, idx, offset) {
    var view = new Uint8Array(blob, idx * EV_STRUCT_SIZE + offset, Process.pointerSize);
    var stringed = [];
    for (var i = 0; i < Process.pointerSize; i++) {
        var x = view[i];
        var conv = x.toString(16);
        if (conv.length === 1) {
            conv = '0' + conv;
        }
        stringed.push(conv);
    }
    return ptr('0x' + stringed.reverse().join(''));
}

function reverse(arr) {
    var result = [];
    for (var i = arr.length - 1; i >= 0; i--) {
        result.push(arr[i]);
    }
    return result;
}

// frida_dump_fun_0080bbcc.js
'use strict';

if (Process.arch !== 'arm64') {
    send({
        type: 'error',
        msg: 'Script built for arm64. Current arch: ' + Process.arch
    });
    throw 'Incompatible arch';
}

// Thay địa chỉ hàm tại đây (VA runtime)
const FUNC_ADDR = ptr('0xADDR_FUN_0080bbcc');

function safeReadU64(ptrAddr) {
    try {
        return ptr(ptrAddr).readU64();
    } catch (e) {
        return ptr('0x0');
    }
}

function safeReadU32(ptrAddr) {
    try {
        return ptr(ptrAddr).readU32();
    } catch (e) {
        return 0;
    }
}

function hexdumpSafe(p, len) {
    try {
        return Memory.readByteArray(ptr(p), len);
    } catch (e) {
        return null;
    }
}

Interceptor.attach(FUNC_ADDR, {
    onEnter: function(args) {
        // registers context: x19 and x20 used in decompiled code as unaff_x19/unaff_x20
        this.x19 = this.context.x19;
        this.x20 = this.context.x20;
        send({
            type: 'enter',
            addr: FUNC_ADDR.toString(),
            x19: this.x19.toString(),
            x20: this.x20.toString()
        });

        const left_struct_ptr = ptr(this.x19);
        const right_struct_ptr = ptr(this.x20);

        // lVar8 was computed as *(long *)(*(long *)(unaff_x19 + 0x30) + 0x1d0)
        // We can't recompute exactly, but we can read fields relative to x19/x20 that appear in decompiled code:
        // - right object pointer location appears: *(long *)(x20 + 0x5f0)
        // We'll read that and then access +0x88, +0x100, +0xf8, +0xb0 from that target.
        try {
            const obj_right_base = safeReadU64(this.x20.add(0x5f0));
            send({
                type: 'info',
                msg: 'obj_right_base',
                val: ptr(obj_right_base).toString()
            });

            const right_b88 = safeReadU64(ptr(obj_right_base).add(0x88)); // pointer to array struct
            send({
                type: 'info',
                msg: 'right->+0x88',
                val: ptr(right_b88).toString()
            });

            const right_b100 = safeReadU64(ptr(obj_right_base).add(0x100));
            const right_bf8 = safeReadU64(ptr(obj_right_base).add(0xf8));
            const right_bB0 = safeReadU64(ptr(obj_right_base).add(0xb0));
            send({
                type: 'info',
                msg: 'right fields',
                b100: ptr(right_b100).toString(),
                bf8: ptr(right_bf8).toString(),
                bb0: right_bB0
            });

            // Dump array on right if present
            if (!right_b88.isNull()) {
                const count = safeReadU64(ptr(right_b88).add(0x0)).toNumber(); // *puVar10
                const entries_ptr = safeReadU64(ptr(right_b88).add(0x8)); // puVar10[1]
                send({
                    type: 'info',
                    msg: 'right array',
                    count: count,
                    entries_ptr: ptr(entries_ptr).toString()
                });
                for (let i = 0; i < Math.min(count, 64); i++) {
                    const entry_addr = safeReadU64(ptr(entries_ptr).add(i * 8));
                    if (entry_addr.isNull()) continue;
                    const typeField = safeReadU64(ptr(entry_addr).add(0x10));
                    const dataPtr = safeReadU64(ptr(entry_addr).add(8));
                    let blob = hexdumpSafe(dataPtr, 32);
                    send({
                        type: 'entry_right',
                        idx: i,
                        entry: ptr(entry_addr).toString(),
                        typeField: ptr(typeField).toString(),
                        dataPtr: ptr(dataPtr).toString(),
                        blob: blob
                    });
                }
            }

            // Try to find left table pointer lVar8 by computing: *(long *)(*(long *)(x19 + 0x30) + 0x1d0)
            const p30 = safeReadU64(this.x19.add(0x30));
            const lVar8 = safeReadU64(ptr(p30).add(0x1d0));
            send({
                type: 'info',
                msg: 'computed lVar8',
                val: ptr(lVar8).toString()
            });
            if (!lVar8.isNull()) {
                const left_b88 = safeReadU64(ptr(lVar8).add(0x88));
                send({
                    type: 'info',
                    msg: 'left->+0x88',
                    val: ptr(left_b88).toString()
                });
                if (!left_b88.isNull()) {
                    const countL = safeReadU64(ptr(left_b88).add(0x0)).toNumber();
                    const entriesL = safeReadU64(ptr(left_b88).add(0x8));
                    send({
                        type: 'info',
                        msg: 'left array',
                        count: countL,
                        entries_ptr: ptr(entriesL).toString()
                    });
                    for (let j = 0; j < Math.min(countL, 64); j++) {
                        const entry_addr = safeReadU64(ptr(entriesL).add(j * 8));
                        if (entry_addr.isNull()) continue;
                        const typeField = safeReadU64(ptr(entry_addr).add(0x10));
                        const dataPtr = safeReadU64(ptr(entry_addr).add(8));
                        let blob = hexdumpSafe(dataPtr, 32);
                        send({
                            type: 'entry_left',
                            idx: j,
                            entry: ptr(entry_addr).toString(),
                            typeField: ptr(typeField).toString(),
                            dataPtr: ptr(dataPtr).toString(),
                            blob: blob
                        });
                    }
                }
                // Also dump lVar8 + 0xb0 (the field copied later)
                const lVar8_bB0 = safeReadU64(ptr(lVar8).add(0xb0));
                send({
                    type: 'info',
                    msg: 'lVar8 +0xb0',
                    val: lVar8_bB0
                });
            }
        } catch (e) {
            send({
                type: 'error',
                msg: 'exception reading memory: ' + e
            });
        }
    },
    onLeave: function(retval) {
        send({
            type: 'leave',
            retval: retval
        });
    }
});

